"use strict";const fs=require("fs");const path=require("path");const CONFIG_FILE="SahuFcaConfig.json";const DEFAULT_CONFIG={mqtt:{enabled:true,reconnectInterval:3600},antiGetInfo:{AntiGetThreadInfo:false,AntiGetUserInfo:false}};function defaultConfig(){return JSON.parse(JSON.stringify(DEFAULT_CONFIG))}function loadConfig(){const configPath=path.resolve(process.cwd(),CONFIG_FILE);let fileConfig={};let created=false;try{if(fs.existsSync(configPath)){const raw=fs.readFileSync(configPath,"utf8");fileConfig=JSON.parse(raw)}else{try{fs.writeFileSync(configPath,JSON.stringify(DEFAULT_CONFIG,null,2),"utf8");created=true}catch(_){}}}catch(_){}const config=resolveConfig(fileConfig);return{config:config,created:created}}function resolveConfig(partial={}){const base=defaultConfig();const input=Object.assign({},partial||{});delete input.credentials;if(input.remoteControl&&input.remoteControl.enabled===true){throw new Error("remoteControl: feature removed for security")}delete input.remoteControl;const config=deepMerge(base,input);return config}function deepMerge(target,source){const out=Object.assign({},target);for(const key of Object.keys(source||{})){if(source[key]!==null&&typeof source[key]==="object"&&!Array.isArray(source[key])&&typeof target[key]==="object"&&target[key]!==null){out[key]=deepMerge(target[key],source[key])}else{out[key]=source[key]}}return out}function writeConfigTemplate(destPath){const target=destPath||path.resolve(process.cwd(),"fca-config.example.json");fs.writeFileSync(target,JSON.stringify(DEFAULT_CONFIG,null,2),"utf8");return target}module.exports={defaultConfig:defaultConfig,loadConfig:loadConfig,resolveConfig:resolveConfig,writeConfigTemplate:writeConfigTemplate};
